// Private, server-only bank. Difficulty describes the authored blueprint;
// it has not been calibrated on candidate responses.
// Each row contains one answer, three distractors and the skills it exercises.
const family = (id, topic, difficulty, rows) => ({
  id, topic, difficulty,
  skills: [...new Set(rows.flatMap(row => row[5]))],
  variants: rows.map(([text, answer, ...rest], index) => {
    const options = rest.slice(0, 3);
    options.splice(index, 0, answer);
    return { id: `${id}-${String.fromCharCode(97 + index)}`, text, options, correct: index, skills: rest[3] };
  }),
});
const program = (...families) => ({ topics: [...new Set(families.map(item => item.topic))], families });

